public static int[] AnalyzeMechina (int[] StudentsMechina)
{
// מוחזר מערך של מספרים אז כדאי להחזיר גם את המכינה
// שאליה נרשמו הכי הרבה נוסף למערך עוד מקום אחד
// ואז המקום האחרון זה בעצם המכינה עם הכי הרבה נרשמים

int[] counter = new int[31]

for(int i=0; i<StudentsMechina; i++)
{
int num = StudentsMechina[i];

counter[num] ++;
}

int count = 0;

for (int i=0; i< counter.length; i++)
{
if (counter[i] > 0)

count++;
}

int[] analyze = new int[count * 2 + 1]; // מניח שהוא מאופס
int j = 0;

for (int i=0; i < counter.length; i++)
{
if (counter[i] > 0)
{
analyze[j] = i;
analyze[j+1] = counter[i];
j+=2
}
if (counter[i] > analyze[count*2]) // לא +1 כי מתחיל ב0

analyze[count*2] = i;
// המכינה עם הכי
}

return analyze;

}
